import { useTooltip } from './useTooltip.js';

export const useSegmentHandlers = () => {
  const {
    hideTooltipHandler,
    showTooltipHandler,
    toggleTooltipPinnedStateHandler,
  } = useTooltip();

  const handleSegmentMouseClick = (event: React.MouseEvent) => {
    event.stopPropagation();

    toggleTooltipPinnedStateHandler();
  };

  const handleSegmentMouseEnter = () => {
    showTooltipHandler();
  };

  const handleSegmentMouseLeave = () => {
    hideTooltipHandler();
  };

  const handleSegmentMouseMove = () => {
    showTooltipHandler();
  };

  return {
    handleSegmentMouseClick,
    handleSegmentMouseEnter,
    handleSegmentMouseLeave,
    handleSegmentMouseMove,
  };
};
